import{_ as l,W as r,s as a,u as d,I as i,ah as n,w as s,Z as p,A as e}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const L=JSON.parse('{"title":"如何找到并杀掉 Linux 系统中的僵尸进程 | LCTT x X-CMD","titleTemplate":false,"description":"如何找到并杀掉 Linux 系统中的僵尸进程 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何找到并杀掉 Linux 系统中的僵尸进程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何找到并杀掉 Linux 系统中的僵尸进程 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211015 How to Find and Kill Zombie Process in Linux","title":"如何找到并杀掉 Linux 系统中的僵尸进程","tag":"202110"},"relativePath":"202110/20211015 How to Find and Kill Zombie Process in Linux.md","filePath":"[post].md"}'),u={name:"202110/20211015 How to Find and Kill Zombie Process in Linux.md"};function m(b,t,f,g,T,x){const o=r("Link");return d(),a("div",null,[t[30]||(t[30]=i("h1",{id:"如何找到并杀掉-linux-系统中的僵尸进程",tabindex:"-1"},[s("如何找到并杀掉 Linux 系统中的僵尸进程 "),i("a",{class:"header-anchor",href:"#如何找到并杀掉-linux-系统中的僵尸进程","aria-label":"Permalink to 如何找到并杀掉 Linux 系统中的僵尸进程"},"​")],-1)),t[31]||(t[31]=i("p",null,[i("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/kill-zombie-process-linux.jpg?resize=800%2C450&ssl=1",alt:""})],-1)),t[32]||(t[32]=i("blockquote",null,[i("p",null,"这是一个关于如何寻找 Linux 系统僵尸进程并杀死它们的小知识。你也可以从中了解到关于进程和僵尸进程的一些知识。")],-1)),t[33]||(t[33]=i("p",null,"在了解僵尸进程之前，让我们来复习一下什么是 Linux 进程。",-1)),i("p",null,[t[1]||(t[1]=s("简而言之，")),p(o,{href:"https://tldp.org/LDP/tlk/kernel/processes.html"},{default:e(()=>t[0]||(t[0]=[s("进程")])),_:1}),t[2]||(t[2]=s(" 是一个程序的运行实例。它可能运行在前端（比如有交互的进程），也可能运行在后端（比如无交互或自动运行的进程）。它可能是一个父进程（运行期间创建了其他进程），也可能是一个子进程（由其他进程所创建）。"))]),t[34]||(t[34]=n('<p>在 Linux 系统中，除 PID 为 0 的第一个 <code>init</code> 进程（或 <code>systemd</code>）外，其余进程都有父进程。进程也可以拥有自己的子进程。</p><p>不相信？可以试试在终端中使用 <code>pstree</code> 命令查看进程的树型结构，你能看到系统各个进程的“家族树”。</p><h3 id="linux系统里的僵尸进程是什么" tabindex="-1">Linux系统里的僵尸进程是什么？ <a class="header-anchor" href="#linux系统里的僵尸进程是什么" aria-label="Permalink to Linux系统里的僵尸进程是什么？">​</a></h3><p>子进程死亡后，它的父进程会接收到通知去执行一些清理操作，如释放内存之类。然而，若父进程并未察觉到子进程死亡，子进程就会进入到“<ruby>僵尸<rt>zombie</rt></ruby>”状态。从父进程角度看，子进程仍然存在，即使子进程实际上已经死亡。这就是“<ruby>僵尸进程<rt>zombie process</rt></ruby>”（也被称为“<ruby>已消失进程<rt>defunct process</rt></ruby>”）是如何产生并存在于系统中的。</p>',4)),i("p",null,[t[4]||(t[4]=s("这里有一个来自 ")),p(o,{href:"https://turnoff.us/geek/zombie-processes/"},{default:e(()=>t[3]||(t[3]=[s("Turnoff.us")])),_:1}),t[5]||(t[5]=s(" 的关于僵尸进程的非常有趣的看法："))]),t[35]||(t[35]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/zombies-turnoff.webp?resize=800%2C467&amp;ssl=1" alt="Image credit: Turnoff.us"></p><h3 id="你真的需要关心僵尸进程吗" tabindex="-1">你真的需要关心僵尸进程吗？ <a class="header-anchor" href="#你真的需要关心僵尸进程吗" aria-label="Permalink to 你真的需要关心僵尸进程吗？">​</a></h3><p>重点要说的是，僵尸进程并没有像它的名称那样看起来可怕。</p><p>但如果系统的内存已经所剩不多或者有太多的僵尸进程在吃掉内存，问题会变得糟糕。同样，大部分 Linux 系统进程最大 PID 设置为 32768，如果过多僵尸进程导致其他重要任务没有 PID 可用，你的系统会发生崩溃。</p><p>这是真实可能发生的，它有一定的概率，特别当存在一个编码糟糕的程序开始大量产生僵尸进程的时候。</p><p>在这种情况下，找到并杀死僵尸进程是一个明智的做法。</p><h3 id="如何找到僵尸进程" tabindex="-1">如何找到僵尸进程 <a class="header-anchor" href="#如何找到僵尸进程" aria-label="Permalink to 如何找到僵尸进程">​</a></h3><p>Linux 系统中的进程可能处于如下状态中的一种：</p><ul><li><code>D</code> = 不可中断的休眠</li><li><code>I</code> = 空闲</li><li><code>R</code> = 运行中</li><li><code>S</code> = 休眠</li><li><code>T</code> = 被调度信号终止</li><li><code>t</code> = 被调试器终止</li><li><code>Z</code> = 僵尸状态</li></ul>',9)),i("p",null,[t[7]||(t[7]=s("那如何查看进程和它的当前状态呢？一个简单的方法是在终端中使用 ")),p(o,{href:"https://linuxhandbook.com/top-command/"},{default:e(()=>t[6]||(t[6]=[s("top 命令")])),_:1}),t[8]||(t[8]=s("。"))]),t[36]||(t[36]=n('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/top-command-view.png?resize=800%2C474&amp;ssl=1" alt="Top command show processes and their status"></p><p>正如你在上面截图中看到的，截图中共有 250 个任务（进程），其中 1 个处在 “<ruby>运行中<rt>running</rt></ruby>” 状态，248 个进程处于 “<ruby>休眠<rt>sleep</rt></ruby>” 状态，还有一个处于 “<ruby>僵尸<rt>zombie</rt></ruby>” 状态。</p><p>现在问题进入下一步，如何杀死 “僵尸” 进程？</p><h3 id="如何找到并杀死一个僵尸进程-僵尸进程能被杀死吗" tabindex="-1">如何找到并杀死一个僵尸进程？僵尸进程能被杀死吗？ <a class="header-anchor" href="#如何找到并杀死一个僵尸进程-僵尸进程能被杀死吗" aria-label="Permalink to 如何找到并杀死一个僵尸进程？僵尸进程能被杀死吗？">​</a></h3><p>僵尸进程已经死了，要如何才能杀死一个已经死亡的进程呢？</p><p>在僵尸电影中，你可以射击僵尸的头部或烧掉它们，但在这里是行不通的。你可以一把火烧了系统来杀死僵尸进程，但这并不是一个可行的方案。</p><p>一些人建议发送 <code>SIGCHLD</code> 给父进程，但这个信号很可能会被忽略。还有一个方法是杀死父进程来杀死僵尸进程，这听起来很野蛮，但它却是唯一能确保杀死僵尸进程的方法。</p>',7)),i("p",null,[t[10]||(t[10]=s("首先，通过在终端中 ")),p(o,{href:"https://linuxhandbook.com/ps-command/"},{default:e(()=>t[9]||(t[9]=[s("使用 ps 命令")])),_:1}),t[11]||(t[11]=s(" 我们列举僵尸进程，得到它们的进程 ID："))]),t[37]||(t[37]=n('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps ux | awk &#39;{if($8==&quot;Z+&quot;) print}&#39;</span></span></code></pre></div><p><code>ps ux</code> 命令输出的第 8 列显示了进程状态。上述命令只会打印所有处在 Z+ 状态（表示僵尸状态）的进程。</p><p>确认了进程 ID 后，我们可以得到它的父进程 ID：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -o ppid= -p &lt;child_id&gt;</span></span></code></pre></div><p>你也可以将上述两个命令结合在一起，直接得到僵尸进程的 PID 及其父进程的 PID：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -A -ostat,pid,ppid | grep -e &#39;[zZ]&#39;</span></span></code></pre></div>',6)),i("p",null,[t[13]||(t[13]=s("现在你得到了父进程 ID，使用命令行和得到的 ID 号 ")),p(o,{href:"https://itsfoss.com/how-to-find-the-process-id-of-a-program-and-kill-it-quick-tip/"},{default:e(()=>t[12]||(t[12]=[s("终于可以杀死进程了")])),_:1}),t[14]||(t[14]=s("："))]),t[38]||(t[38]=n('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -9 &lt;parent_process_ID&gt;</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/killing-parent-process.png?resize=800%2C180&amp;ssl=1" alt="Killing parent process"></p><p>再次运行 <code>ps</code> 命令或 <code>top</code> 命令，你可以验证僵尸进程是否已经被杀死。</p><p>恭喜！现在你知道怎么清理僵尸进程了。</p><hr>',5)),i("p",null,[t[16]||(t[16]=s("via: ")),p(o,{href:"https://itsfoss.com/kill-zombie-process-linux/"},{default:e(()=>t[15]||(t[15]=[s("https://itsfoss.com/kill-zombie-process-linux/")])),_:1})]),i("p",null,[t[21]||(t[21]=s("作者：")),p(o,{href:"https://itsfoss.com/author/marco/"},{default:e(()=>t[17]||(t[17]=[s("Marco Carmona")])),_:1}),t[22]||(t[22]=s(" 选题：")),p(o,{href:"https://github.com/lujun9972"},{default:e(()=>t[18]||(t[18]=[s("lujun9972")])),_:1}),t[23]||(t[23]=s(" 译者：")),p(o,{href:"https://github.com/zengyi1001"},{default:e(()=>t[19]||(t[19]=[s("zengyi1001")])),_:1}),t[24]||(t[24]=s(" 校对：")),p(o,{href:"https://github.com/wxy"},{default:e(()=>t[20]||(t[20]=[s("wxy")])),_:1})]),i("p",null,[t[27]||(t[27]=s("本文由 ")),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>t[25]||(t[25]=[s("LCTT")])),_:1}),t[28]||(t[28]=s(" 原创编译，")),p(o,{href:"https://linux.cn/"},{default:e(()=>t[26]||(t[26]=[s("Linux中国")])),_:1}),t[29]||(t[29]=s(" 荣誉推出"))])])}const P=l(u,[["render",m]]);export{L as __pageData,P as default};
